Here's a simple Python script that accomplishes this task:

```Python
def identify_spans(sentence):
    spans = []
    current_span = ""

    for word in sentence.split():
        if word.lower() == "against" and current_span!= "":
            spans.append("<claim>" + current_span + "</claim>")
            current_span = ""
        elif word.lower() in ["make", "continue"]:
            if current_span!= "":
                spans.append("<premise>" + current_span + "</premise>")
                current_span = ""
        else:
            current_span += word + " "

    if current_span!= "":
        spans.append("<claim>" + current_span.strip() + "</claim>")

    return " ".join(spans)

sentence = "In addition, the separatists continue to make direct threats against the Mission itself."
print(identify_spans(sentence))
```

